 function readPlane(){const rect=shell.getBoundingClientRect(),canvas=document.getElementById('gameCanvas')?.getBoundingClientRect(),hud=shell.querySelector('.game-topbar')?.getBoundingClientRect(),progress=shell.querySelector('.progress-hud')?.getBoundingClientRect();const immersive=shell.classList.contains('immersive')||document.body.classList.contains('shell-experience');const top=immersive?Math.max(0,(hud?.height?hud.bottom:rect.top)-rect.top,(progress?.height?progress.bottom:rect.top)-rect.top):Math.max(0,(canvas?.top||rect.top)-rect.top);plane={left:0,top,width:Math.max(1,rect.width),height:Math.max(120,immersive?rect.height-top:canvas?.height||rect.height-top)};layer.style.setProperty('--ccl-left',plane.left+'px');layer.style.setProperty('--ccl-top',plane.top+'px');layer.style.setProperty('--ccl-width',plane.width+'px');layer.style.setProperty('--ccl-height',plane.height+'px');orientation=plane.width>=plane.height?'landscape':'portrait';return rect;}
 function apply(){if(!targets.size)return;readPlane();const style=getComputedStyle(shell),safe={};for(const side of ['left','right','bottom'])safe[side]=Math.max(7,(parseFloat(style.getPropertyValue('--ccl-safe-'+side))||0)+7);for(const[id,target]of targets){const value=setting(id),size=Math.max(40,Math.min(value.size,plane.width-safe.left-safe.right,plane.height-14)),x=clamp(value.x*plane.width,size/2+safe.left,plane.width-size/2-safe.right),y=clamp(value.y*plane.height,size/2+7,plane.height-size/2-safe.bottom);target.style.setProperty('--ccl-x',x+'px');target.style.setProperty('--ccl-y',y+'px');target.style.setProperty('--ccl-size',size+'px');}selectedUI();}
