 function discover(){const entries=[['joystick',joystick],...[...layer.querySelectorAll('button[data-action]')].filter(e=>names[e.dataset.action]).map(e=>[e.dataset.action,e])];let changed=false;for(const[id,target]of entries)if(!targets.has(id)){targets.set(id,target);target.dataset.campaignLayoutId=id;target.classList.add('campaign-layout-target');const option=document.createElement('option');option.value=id;option.textContent=names[id];choose.append(option);changed=true;}return changed;}
 function sync(){scheduled=false;discover();const s=state(),active=!!s.started&&!s.won&&!s.defeated&&!s.chapterEnded&&!otherMode(),ready=active||editing,playable=active&&!s.paused&&!s.dialog&&!s.cutscene&&!s.activity&&!s.training?.active&&!s.routeTransition;
  for(const[name,value]of[['campaign-layout-ready',ready],['campaign-layout-playable',playable],['campaign-layout-editing',editing]])if(shell.classList.contains(name)!==value)shell.classList.toggle(name,value);
  if(ready)apply();if(!editing){entry.disabled=!!(s.dialog||s.cutscene||s.activity||s.training?.active||s.routeTransition||otherMode());settingsEntry.disabled=entry.disabled;}
 }
